"""Complete the 44-question SLE/APS chapter with original APS questions."""
from create_rheum_lupus_treatment import rows,q,C,S,E,N,K,H,P,ref
from qbank_authoring import finalize
AC=ref('ACR/EULAR 2023 APS classification criteria','https://ard.bmj.com/content/82/10/1258')
AT=ref('EULAR recommendations for adult APS management','https://pmc.ncbi.nlm.nih.gov/articles/PMC11034817/')
BS=ref('BSH 2024 APS investigation and management guideline','https://doi.org/10.1111/bjh.19635')
L=ref('ISTH-SSC updated antiphospholipid antibody laboratory guidance, 2025','https://doi.org/10.1016/j.jtha.2024.10.022')

q('A woman has an unprovoked proximal DVT and persistent lupus anticoagulant plus high-titer anticardiolipin antibodies. Which diagnosis is most likely?', 'Thrombotic antiphospholipid syndrome',[
 ('Acquired hemophilia A','This generally causes bleeding with an acquired factor VIII inhibitor, not this characteristic thrombosis/aPL pattern.'),('Immune thrombocytopenia alone','Isolated platelet disease does not explain the full thrombotic antibody phenotype.'),('Isolated transient infection-related aPL positivity','The stated persistence and objective thrombosis make this explanation inadequate.')],
 'Combine the clinical event with persistent relevant antibodies','**APS is a thrombo-inflammatory syndrome associated with persistent aPL.**',['Venous, arterial, microvascular and obstetric manifestations can occur.','SLE can coexist but is not required.'], '**Document the event, antibody type, persistence and alternative risk factors.**',['Begin appropriate thrombosis treatment without waiting for all repeat testing when an acute event is established.','Classification criteria are designed for research specificity and do not replace clinical diagnosis.'],[['Thrombosis','Objective clinical evidence'],['aPL','Relevant persistent laboratory evidence'],['SLE','May be present or absent']],[AC,BS],style='clinical_scenario')

q('What minimum interval is conventionally used to establish persistent positivity of criterion antiphospholipid antibodies?', 'At least 12 weeks',[
 ('48 hours','This does not distinguish persistent antibodies from a transient acute result.'),('2 weeks','This is shorter than the accepted persistence interval.'),('6 weeks','This is also shorter than the conventional 12-week interval.')],
 'Transient antibody positivity is not the same as persistence','**Repeat positive tests at least twelve weeks apart support persistence.**',['Interpret antibody titer, assay method and relevant clinical phenotype.','Acute illness and anticoagulants can complicate particular tests.'], '**Plan repeat testing without delaying necessary treatment of a proven thrombotic event.**',['Avoid diagnosing APS from an isolated low-titer result alone.','The 2023 classification framework adds timing and weighted-domain rules for research.'],[['Repeat interval','At least 12 weeks'],['Single result','Can be transient'],['Clinical context','Still essential']],[AC,L])

q('Why can a lupus anticoagulant prolong an aPTT while being associated clinically with thrombosis?', 'It interferes with phospholipid-dependent clotting assays in vitro, while the in-vivo syndrome is prothrombotic',[
 ('It always causes severe factor VIII deficiency','A specific factor VIII inhibitor is a different mechanism and typically a bleeding concern.'),('It is a circulating therapeutic heparin preparation','LA is an antibody-related laboratory phenomenon, although heparin can interfere with testing.'),('It lowers fibrinogen to zero in every patient','This is not the defining LA mechanism.')],
 'The name describes the assay effect, not the usual clinical outcome','**LA produces a phospholipid-dependent inhibitory effect in clot-based testing.**',['A prolonged clotting time is not equivalent to protection from thrombosis.','Some LA-positive patients have bleeding for other reasons, so the complete hemostatic assessment still matters.'], '**Use appropriate screen, mixing and confirmatory laboratory methods.**',['Review anticoagulant exposure.','Do not assume LA positivity means the patient has SLE.'],[['In vitro','Prolonged phospholipid-dependent assay'],['In vivo','Association with thrombosis'],['Name','Does not require SLE']],[L])

q('A patient with bruising and major soft-tissue bleeding has an isolated prolonged aPTT that fails to correct on mixing. What additional distinction is essential before calling this lupus anticoagulant?', 'Assess for a specific factor inhibitor, especially factor VIII, and anticoagulant interference',[
 ('Assume noncorrection proves APS','Noncorrection indicates an inhibitor-type effect but does not uniquely identify LA.'),('Assume all coagulation factor levels must be normal','Specific factor inhibitors can reduce functional activity.'),('Use an isolated positive ANA to settle the clotting diagnosis','ANA does not identify the cause of the aPTT abnormality.')],
 'A mixing study narrows mechanisms but does not name the inhibitor','**Both LA and specific factor inhibitors can cause noncorrection.**',['The bleeding phenotype particularly raises concern for acquired hemophilia.','Incubation effects, factor assays and phospholipid-dependent confirmatory tests help distinguish causes.'], '**Investigate serious bleeding urgently.**',['Review heparin/DOAC exposure and laboratory methods.','Treatment of acquired hemophilia differs substantially from APS thrombosis management.'],[['Noncorrection','Inhibitor or drug effect'],['Major soft-tissue bleeding','Consider acquired factor VIII inhibitor'],['LA confirmation','Requires appropriate phospholipid-dependent testing']],[L,BS],style='clinical_scenario')

q('A patient taking rivaroxaban has a positive lupus anticoagulant assay obtained during treatment. Which interpretation is best?', 'The result may be affected by the anticoagulant and needs expert, method-aware confirmation',[
 ('The result alone establishes lifelong APS','Anticoagulant interference can cause misleading results.'),('Rivaroxaban cannot affect any clot-based LA assay','DOACs can cause false-positive or false-negative clot-based results.'),('All anticoagulation should be stopped immediately without a thrombosis plan','Unsupervised interruption can be dangerous and is not a diagnostic strategy.')],
 'Know what the assay is measuring in the presence of a drug','**DOAC exposure can substantially distort LA testing.**',['Drug levels, timing, validated removal methods or alternative strategies may be used by specialist laboratories.','Solid-phase anticardiolipin and anti-beta2GPI assays have different interference considerations.'], '**Coordinate testing without creating avoidable thrombotic risk.**',['Document the drug and last dose on the request.','Use repeat and confirmatory testing appropriate to the clinical question.'],[['Clot-based LA','Potential DOAC interference'],['Solid-phase antibodies','Different assay principles'],['Testing plan','Specialist interpretation']],[L,ref('ISTH-SSC LA testing during anticoagulation guidance','https://www.jthjournal.org/article/S1538-7836%2822%2901344-7/fulltext')],style='clinical_scenario')

q('What does triple-positive APS serology mean?', 'Lupus anticoagulant, anticardiolipin and anti-beta2-glycoprotein I positivity',[
 ('ANA, anti-dsDNA and anti-Sm positivity','These are SLE-related antibodies, not the APS triple-positive definition.'),('RF, anti-CCP and ANA positivity','These do not define an APS high-risk profile.'),('Anti-Ro, anti-La and anti-U1 RNP positivity','These belong to other connective-tissue disease associations.')],
 'Recognize a high-risk aPL profile','**Triple positivity involves all three established aPL assay groups.**',['Persistence and titer matter, and LA itself is an important risk marker.','A high-risk profile changes prevention and anticoagulant discussions but does not replace the clinical phenotype.'], '**Record exactly which antibodies were measured.**',['Do not use the term triple-positive for any three autoimmune antibodies.','Interpret results with assay-specific standards and clinical history.'],[['LA','Functional clot-based test'],['aCL','Solid-phase antibody'],['Anti-beta2GPI','Solid-phase antibody']],[AC,AT])

q('A patient has definite APS and a first unprovoked proximal venous thrombosis. Which long-term regimen is generally preferred?', 'A vitamin K antagonist with target INR 2–3',[
 ('Aspirin alone','Antiplatelet monotherapy is generally inadequate secondary prevention for this venous APS scenario.'),('Rivaroxaban as the preferred choice in triple-positive disease','High-risk APS has evidence against routine rivaroxaban substitution.'),('Prednisone alone','Immunosuppression does not substitute for anticoagulation of thrombotic APS.')],
 'Treat the thrombotic mechanism with appropriate anticoagulation','**Long-term VKA treatment at INR two to three is a standard strategy after unprovoked venous APS thrombosis.**',['Duration and intensity require bleeding-risk and recurrence assessment.','The acute event is initially managed with appropriate anticoagulation before the long-term plan is established.'], '**Provide INR, interaction and adherence counseling.**',['Review perioperative interruption and bridging plans when relevant.','Confirm that the laboratory INR method is appropriate if results appear unreliable.'],[['Venous APS','VKA usually preferred'],['Usual initial VKA target','INR 2–3'],['Aspirin alone','Not adequate for this secondary prevention setting']],[AT,BS],style='clinical_scenario')

q('Which APS phenotype provides the clearest reason to avoid routine substitution of rivaroxaban for warfarin?', 'Triple-positive APS, especially with arterial events',[
 ('A single transient low-titer aCL during viral illness without thrombosis','This does not establish thrombotic APS or a need for anticoagulation.'),('Isolated ANA positivity with no thrombotic history','This does not define APS.'),('A remote uncomplicated superficial bruise with negative aPL testing','This is not a high-risk APS phenotype.')],
 'Do not generalize usual VTE DOAC practice to high-risk APS','**High-risk APS has shown excess recurrent events with DOAC strategies in important trials.**',['The strongest concern includes triple-positive and arterial APS populations.','Selected lower-risk situations require specialist discussion rather than an automatic class-wide substitution.'], '**Assess the reason for considering a switch.**',['Improve VKA support when poor INR control reflects remediable adherence or access issues.','Explain the evidence rather than selecting solely for convenience.'],[['Triple-positive/arterial APS','Strong DOAC concern'],['VKA','Usual preferred long-term treatment'],['Other profiles','Individualized specialist assessment']],[BS,AT,ref('TRAPS randomized trial: rivaroxaban versus warfarin','https://doi.org/10.1182/blood-2018-04-848333')])

q('A patient with definite APS has an ischemic stroke. Which long-term antithrombotic principle is appropriate?', 'Use a VKA-based strategy with intensity and possible antiplatelet addition individualized to recurrence and bleeding risk',[
 ('Treat every patient indefinitely with aspirin alone regardless of APS risk','Definite arterial APS generally warrants a stronger VKA-based approach.'),('Use the same low-dose prophylactic LMWH as routine inpatient VTE prevention','This is not equivalent to therapeutic secondary prevention after arterial APS.'),('Prefer a DOAC automatically because the event was arterial','Arterial APS is an important setting of DOAC concern.')],
 'Arterial APS needs a risk-based secondary prevention plan','**A VKA-based approach is generally preferred after arterial APS thrombosis.**',['Guidelines discuss INR two to three or higher-intensity strategies in selected circumstances, considering bleeding risk.','The evidence is less definitive for one universal intensity than for standard venous APS care.'], '**Confirm event mechanism and address conventional vascular risks.**',['Acute stroke management follows its time-sensitive pathway.','Recurrence despite apparently adequate treatment requires adherence, INR and alternative-cause review.'],[['Arterial APS','VKA-based prevention'],['Intensity','Individualized'],['Recurrence','Review treatment and mechanisms']],[AT,BS],style='clinical_scenario')

q('A pregnant woman has obstetric APS with recurrent qualifying pregnancy losses but no previous thrombosis. Which regimen is generally used?', 'Low-dose aspirin plus prophylactic-dose heparin, usually LMWH',[
 ('Warfarin throughout pregnancy without modification','Warfarin has fetal risks and is not the usual obstetric APS regimen.'),('Therapeutic-dose LMWH in every patient solely because of pregnancy losses','Therapeutic dosing is generally reserved for thrombotic APS or other specific indications.'),('Hydroxychloroquine alone as a substitute for antithrombotic treatment in every case','It may have an adjunctive role but does not routinely replace aspirin/heparin in established obstetric APS.')],
 'Distinguish obstetric from thrombotic APS dosing','**Aspirin plus prophylactic heparin is a standard obstetric APS strategy without prior thrombosis.**',['Timing, postpartum prevention and adjustments depend on the clinical history and specialist plan.','Refractory pregnancy morbidity requires reassessment and possible additional strategies.'], '**Coordinate maternal-fetal and thrombosis care.**',['Review bleeding risks and delivery/neuraxial timing.','Continue appropriate SLE disease control when lupus coexists.'],[['Obstetric APS without thrombosis','Aspirin + prophylactic heparin'],['Prior thrombotic APS','Usually therapeutic anticoagulation'],['Delivery/postpartum','Requires an explicit plan']],[AT,P],style='clinical_scenario')

q('How does pregnancy management usually differ for a woman with thrombotic APS and a previous proximal DVT?', 'Therapeutic-dose heparin is generally used with low-dose aspirin during pregnancy',[
 ('No anticoagulation is needed once the prior DVT has resolved','Prior thrombotic APS remains a major recurrence risk.'),('Only a routine low-dose inpatient prophylaxis regimen is sufficient for every pregnancy','This understates the need for therapeutic anticoagulation in thrombotic APS.'),('Warfarin is always continued unchanged through organogenesis','Fetal risks require a specialist pregnancy anticoagulation plan.')],
 'Prior thrombosis changes the intensity','**Thrombotic APS generally requires therapeutic anticoagulation during pregnancy.**',['LMWH is commonly used, with aspirin according to the APS plan.','Medication transition, renal function and delivery planning require specialist oversight.'], '**Plan both antepartum and postpartum treatment.**',['Avoid unsupervised interruption.','Discuss breastfeeding-compatible postpartum anticoagulation options when relevant.'],[['Prior thrombotic APS','Therapeutic heparin strategy'],['Obstetric-only APS','Usually prophylactic heparin strategy'],['Postpartum','Continued thrombosis prevention/treatment plan']],[AT,P],style='clinical_scenario')

q('A patient with known APS develops renal, pulmonary and neurological microvascular injury within 5 days after infection. Which treatment combination is generally first-line for suspected catastrophic APS?', 'Heparin, glucocorticoids and plasma exchange and/or IVIG, with treatment of the trigger',[
 ('Aspirin alone','This is insufficient for a rapidly progressive multiorgan thrombotic syndrome.'),('Warfarin alone while waiting weeks for repeat aPL testing','Urgent treatment should not wait for research classification confirmation.'),('High-dose glucocorticoids alone without anticoagulation or trigger treatment','Combination therapy addresses several components of the syndrome.')],
 'Recognize a rapidly evolving thrombo-inflammatory emergency','**CAPS can involve multiple organs over days and requires urgent multidisciplinary care.**',['Infection, surgery or anticoagulation interruption can be triggers.','DIC, TTP, complement-mediated TMA and other critical illnesses are important overlapping differentials.'], '**Begin appropriate combined treatment when clinical suspicion is strong.**',['Support failing organs and manage infection concurrently.','Refractory disease may require specialist-directed B-cell or complement-targeted approaches.'],[['Anticoagulation','Usually heparin'],['Inflammation/immune factors','Glucocorticoids + exchange/IVIG'],['Trigger','Actively identify and treat']],[AT,BS],style='clinical_scenario')

q('An asymptomatic person has persistently high-risk aPL, including lupus anticoagulant, but has never had thrombosis or qualifying obstetric morbidity. Which statement is correct?', 'This is an aPL-positive high-risk carrier state; primary prevention is individualized and low-dose aspirin may be recommended',[
 ('Lifelong full-dose warfarin is mandatory solely from the antibody results','Therapeutic anticoagulation is not automatically indicated without a clinical event.'),('The antibody profile has no relevance to future risk','High-risk profiles influence prevention and counseling.'),('The person must have SLE','APS-associated antibodies can occur without SLE.')],
 'Antibody carriage differs from established thrombotic APS','**Primary prevention depends on the aPL profile and clinical risk factors.**',['EULAR recommends low-dose aspirin for selected high-risk carriers after benefit-risk assessment.','Control smoking, hypertension and other vascular risks and plan prophylaxis in high-risk situations.'], '**Do not expose every carrier to full anticoagulation.**',['Confirm persistence and review testing quality.','Discuss surgery, immobilization, estrogen exposure and pregnancy as appropriate.'],[['No clinical event','Carrier state rather than thrombotic APS'],['High-risk aPL','Prevention discussion'],['Full-dose anticoagulation','Not automatic']],[AT,BS])

q('A patient with thrombotic APS has platelets of 95,000/µL without bleeding. What is the best general interpretation?', 'Moderate thrombocytopenia can coexist with thrombotic risk and does not automatically remove the anticoagulation indication',[
 ('Thrombocytopenia proves that thrombosis cannot occur','APS can produce both low platelets and thrombosis.'),('The platelet count alone proves TTP','TTP requires a compatible microangiopathic syndrome and ADAMTS13 assessment.'),('All antithrombotic treatment must be permanently stopped at any platelet count below normal','Decisions depend on platelet severity, bleeding and thrombotic risk rather than any subnormal value.')],
 'Low platelets do not always mean low thrombosis risk','**APS-associated thrombocytopenia is often mild or moderate.**',['Assess medications, infection, immune platelet destruction and microangiopathy.','Severe thrombocytopenia or active bleeding requires a different individualized safety plan.'], '**Balance bleeding and clotting risks with specialist input.**',['Review trends rather than one isolated count.','Do not diagnose a new mechanism without evaluating the accompanying clinical and laboratory findings.'],[['Moderate low platelets','Can coexist with thrombosis'],['Microangiopathic hemolysis','Investigate TMA'],['Anticoagulation','Risk-based decision']],[BS,AC],style='clinical_scenario')

q('A patient with SLE has sterile mitral valve vegetations and embolic events after infective endocarditis has been carefully excluded. Which lesion is most characteristic?', 'Libman–Sacks endocarditis',[
 ('Rheumatic commissural fusion','This is a different post-streptococcal structural valve process.'),('Isolated calcific aortic stenosis','This does not explain sterile mitral vegetations in this context.'),('Atrial myxoma','This is an intracardiac tumor, usually attached at a characteristic atrial site rather than a valve vegetation.')],
 'Consider nonbacterial thrombotic valvular disease','**Libman–Sacks lesions occur in SLE and can be associated with aPL.**',['Exclude infection using the full clinical, microbiological and imaging assessment.','Valve lesions can produce regurgitation or embolism.'], '**Evaluate both lupus activity and the thrombotic phenotype.**',['Management may include disease control and antithrombotic treatment when indicated.','A sterile label should not be assigned from one negative culture after prior antibiotics.'],[['Infective endocarditis','Microbiology and clinical evidence'],['Libman–Sacks','Sterile immune/thrombotic lesions'],['Embolic risk','Requires mechanism-directed assessment']],[S,AC],style='clinical_scenario')

q('A woman with SLE develops thrombocytopenia, microangiopathic hemolytic anemia and fluctuating neurological symptoms. Which test is especially important for identifying immune TTP?', 'ADAMTS13 activity with inhibitor/antibody assessment',[
 ('ANA titer alone','This confirms neither TTP nor the cause of the microangiopathy.'),('Serum urate alone','It does not establish severe ADAMTS13 deficiency.'),('Anti-CCP alone','This is not a TMA mechanism test.')],
 'Do not call every lupus-associated TMA catastrophic APS','**Severe ADAMTS13 deficiency supports TTP and changes urgent treatment.**',['CAPS, complement-mediated TMA, severe hypertension, drugs and pregnancy-related disease are alternatives.','Draw the sample before plasma treatment when feasible, but do not delay urgent therapy in a highly suspected case.'], '**Use the clinical syndrome to guide immediate hematological care.**',['Plasma exchange, immunosuppression and selected caplacizumab are relevant to immune TTP pathways.','Identify renal, neurological and other organ injury and concurrent lupus activity.'],[['ADAMTS13','Defines a key TTP mechanism'],['aPL/CAPS assessment','Different thrombotic mechanism'],['Urgent treatment','Should not await slow confirmatory testing']],[K,ref('ISTH guidelines for TTP diagnosis','https://doi.org/10.1111/jth.15006')],style='clinical_scenario')

if __name__=='__main__':finalize('Rheumatology',4,'Systemic Lupus Erythematosus and Antiphospholipid Syndrome','rheum-sle-aps',rows,44)
